import{_ as e,o as i,c as a,ae as t}from"./chunks/framework.Dh1jimFm.js";const p=JSON.parse('{"title":"Voice Commands (Supervoice)","description":"","frontmatter":{},"headers":[],"relativePath":"tools/voice-commands.md","filePath":"tools/voice-commands.md"}'),n={name:"tools/voice-commands.md"};function s(r,o,c,l,d,m){return i(),a("div",null,o[0]||(o[0]=[t('<h1 id="voice-commands-supervoice" tabindex="-1">Voice Commands (Supervoice) <a class="header-anchor" href="#voice-commands-supervoice" aria-label="Permalink to &quot;Voice Commands (Supervoice)&quot;">​</a></h1><p>Supervertaler includes <strong>Supervoice</strong>: voice dictation + Talon-style voice commands.</p><h2 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to &quot;Where to find it&quot;">​</a></h2><ul><li>Go to the <strong>Tools</strong> tab → <strong>🎤 Supervoice</strong>.</li></ul><h2 id="push-to-talk-dictation-f9" tabindex="-1">Push-to-talk dictation (F9) <a class="header-anchor" href="#push-to-talk-dictation-f9" aria-label="Permalink to &quot;Push-to-talk dictation (F9)&quot;">​</a></h2><ul><li>Press <code>F9</code> to start recording.</li><li>Speak.</li><li>Supervertaler transcribes what you said.</li></ul><p>If voice commands are enabled, Supervertaler will first try to interpret your speech as a command. If nothing matches, the text is inserted as dictation.</p><h2 id="voice-commands" tabindex="-1">Voice commands <a class="header-anchor" href="#voice-commands" aria-label="Permalink to &quot;Voice commands&quot;">​</a></h2><p>Voice commands trigger actions like navigation and editing.</p><p>Examples of built-in phrases include:</p><ul><li>“next segment”</li><li>“previous segment”</li><li>“confirm”</li><li>“copy source”</li><li>“clear target”</li></ul><p>You can add/edit/remove commands in <strong>🎤 Supervoice</strong>.</p><h2 id="always-on-listening-mode" tabindex="-1">Always-on listening mode <a class="header-anchor" href="#always-on-listening-mode" aria-label="Permalink to &quot;Always-on listening mode&quot;">​</a></h2><p>Always-on mode continuously listens for speech and automatically:</p><ol><li>Detects when you start speaking</li><li>Records</li><li>Transcribes</li><li>Runs it as a command or dictation</li></ol><p>This is configured and toggled inside <strong>🎤 Supervoice</strong>.</p><h2 id="recognition-engine" tabindex="-1">Recognition engine <a class="header-anchor" href="#recognition-engine" aria-label="Permalink to &quot;Recognition engine&quot;">​</a></h2><p>Supervoice supports two transcription modes:</p><ul><li><strong>Local Whisper (offline)</strong>: runs on your computer (slower, depends on your hardware)</li><li><strong>OpenAI Whisper API (online)</strong>: faster and usually much more accurate for short commands (requires an OpenAI API key)</li></ul><h2 id="autohotkey-system-commands" tabindex="-1">AutoHotkey (system commands) <a class="header-anchor" href="#autohotkey-system-commands" aria-label="Permalink to &quot;AutoHotkey (system commands)&quot;">​</a></h2><p>Some voice commands can execute AutoHotkey scripts to control other applications (for example: memoQ or Trados).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If AutoHotkey is not installed, in-app commands still work, but system-level commands won’t.</p></div><h2 id="tips-for-accuracy" tabindex="-1">Tips for accuracy <a class="header-anchor" href="#tips-for-accuracy" aria-label="Permalink to &quot;Tips for accuracy&quot;">​</a></h2><ul><li>Use a quiet environment and a consistent mic position.</li><li>If recognition triggers too easily (or not at all), adjust <strong>Mic Sensitivity</strong> in <strong>🎤 Supervoice</strong>.</li></ul>',24)]))}const h=e(n,[["render",s]]);export{p as __pageData,h as default};
